import itertools
coords8=[(9,9),(15,9),(21,9),(9,17),(21,17),(9,25),(15,25),(21,25)]
def combo_sequence(group):
    seq=[]; cur=set()
    for c in group:
        for b in cur-set(c):seq.append(b)
        for b in set(c)-cur:seq.append(b)
        cur=set(c)
    return seq
G=list(itertools.combinations(range(2,8),2)); group=[(0,1)+c for c in G]
seq=combo_sequence(group)
print(len(seq),[(group[i],group[i+1]) for i in range(2)])
print([{'id':6,'x':coords8[b][0],'y':coords8[b][1]} for b in seq])
